// Fetch wishlist items for either logged-in user or guest (resolved via API)
useEffect(() => {
  const fetchWishlist = async () => {
    if (user) {
      try {
        const res = await fetch(`${apiBase}/api/me/wishlist`, { credentials: "include" });
        if (res.ok) {
          const data = await res.json();
          setWishlistItems(data || []);
        }
      } catch (err) {
        console.error(err);
      }
    } else {
      if (ids && ids.length > 0) {
        try {
          const res = await fetch(`${apiBase}/api/products`, { cache: "no-store" });
          if (res.ok) {
            const data = await res.json();
            const allProducts = data.results || [];
            const resolved = ids.map(id => {
              const prod = allProducts.find(p => String(p.id) === String(id)) || placeholderFeatured.find(p => String(p.id) === String(id));
              if (prod) {
                return {
                  product_id: prod.id,
                  name: prod.name_fa,
                  slug: prod.slug,
                  price: Number(prod.price) || Number(prod.min_price) || 0,
                  image: prod.image_url || prod.image
                };
              }
              return null;
            }).filter(Boolean);
            setWishlistItems(resolved);
          }
        } catch (err) {
          console.error(err);
        }
      } else {
        setWishlistItems([]);
      }
    }
  };

  fetchWishlist();
}, [ids, user, apiBase]);

